def restore_before_fixed_scripts(text):
    if type(text) is not str:
        raise AssertionError("Fixture inverse expects source text")
    if "const FIXED_VALIDATOR_SCRIPTS:" not in text:
        return text
    for expected, replacement in _FIXED_SCRIPT_EDITS:
        if text.count(expected) != 1:
            raise AssertionError("Unknown fixed script fixture anchor refused")
        text = text.replace(expected, replacement, 1)
    return text
